function label(text,p){const c=document.createElement('canvas');c.width=256;c.height=256;const x=c.getContext('2d');x.font='bold '+(text.length>1?124:156)+'px Arial';x.textAlign='center';x.textBaseline='middle';x.lineJoin='round';x.strokeStyle=text==='H'?'#ffffff':'#172940';x.lineWidth=10;x.strokeText(text,128,134);x.fillStyle=text==='H'?'#172940':'#ffffff';x.fillText(text,128,134);const texture=new T.CanvasTexture(c);texture.colorSpace=T.SRGBColorSpace;const m=new T.SpriteMaterial({map:texture,depthTest:true,depthWrite:false,transparent:true,fog:false});const sprite=new T.Sprite(m);sprite.scale.set(text==='H'?.29:.39,text==='H'?.29:.39,1);sprite.position.copy(p);sprite.userData.element=text;sprite.userData.atomPosition=p.clone();sprite.userData.radius=text==='H'?.20:.34;sprite.renderOrder=4;labelGroup.add(sprite);}
