function navigationRect(clientX){const r=$('viewer').getBoundingClientRect();if(representation()!=='comparison')return r;const width=r.width/2;return {width,height:r.height,left:r.left+(clientX>=r.left+width?width:0),top:r.top};}
function potentialStops(){const palette=$('surfaceColor').value;return palette==='rainbow'?[[0,[1,0,0]],[.25,[1,1,0]],[.5,[0,1,0]],[.75,[0,1,1]],[1,[0,0,1]]]:palette==='alternative'?[[0,[.43,.19,.64]],[.5,[.98,.98,.98]],[1,[.77,.34,.02]]]:[[0,[.77,.13,.22]],[.5,[.98,.98,.98]],[1,[.14,.33,.77]]]}
